final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Creates an AWS IoT Core device onboarding policy that allows devices to
  connect, publish and subscribe to MQTT topics scoped to their own thing
  name. The policy is generated by a Lambda-backed CloudFormation custom
  resource running Node.js 24.x and the generated policy name is exposed as
  a stack output.

Metadata:
  AWS::CloudFormation::Interface:
    ParameterGroups:
      - Label:
          default: IoT Device Onboarding Policy
        Parameters:
          - PolicyNamePrefix
          - ThingName
          - TopicFilter
      - Label:
          default: Custom Resource Lambda Settings
        Parameters:
          - LambdaLogRetentionDays
    ParameterLabels:
      PolicyNamePrefix:
        default: Policy name prefix
      ThingName:
        default: Thing name pattern
      TopicFilter:
        default: Topic filter
      LambdaLogRetentionDays:
        default: Lambda log retention (days)

Parameters:
  PolicyNamePrefix:
    Type: String
    Default: device-onboarding-policy
    Description: Prefix for the generated IoT policy name. A stack-unique suffix is appended automatically.
    AllowedPattern: '^[A-Za-z0-9=@,._-]{1,64}$'
    ConstraintDescription: Policy name prefix must be 1-64 characters from [A-Za-z0-9=@,._-].
  ThingName:
    Type: String
    Default: '${iot:Connection.Thing.ThingName}'
    Description: >-
      Thing name used to scope the policy. Keep the default AWS IoT policy
      variable so every device is scoped to its own thing name, or provide a
      specific thing name for a single-device policy.
  TopicFilter:
    Type: String
    Default: '*'
    Description: Topic suffix appended to the thing name, for example * allows all subtopics of the thing.
    AllowedPattern: '^[A-Za-z0-9_+#*/=@,.:-]{1,64}$'
    ConstraintDescription: Topic filter must be 1-64 characters from [A-Za-z0-9_+#*/=@,.:-].
  LambdaLogRetentionDays:
    Type: Number
    Default: 14
    Description: CloudWatch Logs retention in days for the custom resource Lambda log group.
    AllowedValues:
      - 1
      - 3
      - 5
      - 7
      - 14
      - 30
      - 60
      - 90
      - 120
      - 150
      - 180
      - 365
      - 400
      - 545
      - 731
      - 1827
      - 3653

Resources:
  OnboardingPolicyLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role for the IoT device onboarding policy custom resource Lambda.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: 'sts:AssumeRole'
      ManagedPolicyArns:
        - !Sub 'arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole'
      Policies:
        - PolicyName: iot-onboarding-policy-management
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: ManageIoTDevicePolicies
                Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:CreatePolicyVersion
                  - iot:SetDefaultPolicyVersion
                  - iot:ListPolicyVersions
                  - iot:DeletePolicyVersion
                  - iot:DeletePolicy
                  - iot:ListTargetsForPolicy
                  - iot:DetachPolicy
                Resource: '*'
      Tags:
        - Key: Purpose
          Value: iot-device-onboarding

  OnboardingPolicyLambdaFunction:
    Type: AWS::Lambda::Function
    Properties:
      Description: Custom resource handler that creates, updates and deletes the IoT device onboarding policy.
      Runtime: nodejs24.x
      Handler: index.handler
      MemorySize: 128
      Timeout: 120
      Role: !GetAtt OnboardingPolicyLambdaRole.Arn
      Environment:
        Variables:
          IOT_REGION: !Sub '${AWS::Region}'
          IOT_ACCOUNT_ID: !Sub '${AWS::AccountId}'
      Tags:
        - Key: Purpose
          Value: iot-device-onboarding
      Code:
        ZipFile: |
          const I = require('@aws-sdk/client-iot');
          const crypto = require('crypto');
          const iot = new I.IoTClient({});
          const R = process.env.IOT_REGION;
          const A = process.env.IOT_ACCOUNT_ID;
          const THING = '${iot:Connection.Thing.ThingName}';
          const nf = (e) => e && e.name === 'ResourceNotFoundException';
          const P = (n) => ({ policyName: n });

          function doc(thing, filter) {
            const t = String(thing || THING).trim();
            const f = String(filter || '*').trim();
            if (!t || /["'\s]/.test(t)) throw new Error('Invalid ThingName');
            if (!/^[A-Za-z0-9_+#*/=@,.:-]{1,64}$/.test(f)) throw new Error('Invalid TopicFilter');
            const b = 'arn:aws:iot:' + R + ':' + A;
            return { Version: '2012-10-17', Statement: [
              { Sid: 'Connect', Effect: 'Allow', Action: 'iot:Connect', Resource: b + ':client/' + t },
              { Sid: 'Publish', Effect: 'Allow', Action: 'iot:Publish', Resource: [b + ':topic/' + t + '/' + f] },
              { Sid: 'Subscribe', Effect: 'Allow', Action: 'iot:Subscribe', Resource: [b + ':topicfilter/' + t + '/' + f] },
              { Sid: 'Receive', Effect: 'Allow', Action: 'iot:Receive', Resource: [b + ':topic/' + t + '/' + f] }] };
          }

          function name(props, event) {
            const p = String(props.PolicyNamePrefix || 'device-onboarding-policy').replace(/[^A-Za-z0-9=@,._-]/g, '-');
            const h = crypto.createHash('sha256').update((event.StackId || '') + '/' + (event.LogicalResourceId || '')).digest('hex').slice(0, 8);
            return p.slice(0, 118) + '-' + h;
          }

          async function upsert(n, d) {
            try { await iot.send(new I.CreatePolicyCommand({ ...P(n), policyDocument: d })); }
            catch (e) {
              if (e.name !== 'ResourceAlreadyExistsException') throw e;
              const old = await iot.send(new I.ListPolicyVersionsCommand(P(n)));
              await iot.send(new I.CreatePolicyVersionCommand({ ...P(n), policyDocument: d, setAsDefault: true }));
              for (const v of old.versions || []) {
                try { await iot.send(new I.DeletePolicyVersionCommand({ ...P(n), policyVersionId: v.versionId })); }
                catch (err) { console.warn('Skip ' + v.versionId); }
              }
            }
          }

          async function remove(n) {
            let m;
            do {
              const t = await iot.send(new I.ListTargetsForPolicyCommand({ ...P(n), marker: m, pageSize: 100 }));
              for (const x of t.targets || []) {
                try { await iot.send(new I.DetachPolicyCommand({ ...P(n), target: x })); }
                catch (err) { console.warn('Skip detach ' + x); }
              }
              m = t.nextMarker;
            } while (m);
            const vs = await iot.send(new I.ListPolicyVersionsCommand(P(n)));
            for (const v of vs.versions || []) {
              if (!v.isDefaultVersion) {
                try { await iot.send(new I.DeletePolicyVersionCommand({ ...P(n), policyVersionId: v.versionId })); }
                catch (err) { console.warn('Skip ' + v.versionId); }
              }
            }
            await iot.send(new I.DeletePolicyCommand(P(n)));
          }

          const send = (e, c, s, d, id) => fetch(e.ResponseURL, { method: 'PUT', body: JSON.stringify({
            Status: s,
            Reason: s === 'SUCCESS' ? 'Log stream: ' + c.logStreamName : ((d && d.Error) || 'Unknown error'),
            PhysicalResourceId: id || c.logStreamName,
            StackId: e.StackId, RequestId: e.RequestId, LogicalResourceId: e.LogicalResourceId,
            Data: d || {} }) });

          exports.handler = async (event, context) => {
            console.log(JSON.stringify(event));
            let id = event.PhysicalResourceId;
            try {
              const p = event.ResourceProperties || {};
              const d = JSON.stringify(doc(p.ThingName, p.TopicFilter));
              if (event.RequestType === 'Delete') {
                try { await remove(id); } catch (err) { if (!nf(err)) throw err; }
              } else {
                id = name(p, event);
                await upsert(id, d);
              }
              const data = event.RequestType === 'Delete' ? {} : { PolicyName: id };
              await send(event, context, 'SUCCESS', data, id);
            } catch (err) {
              console.error(err && err.stack ? err.stack : err);
              await send(event, context, 'FAILED', { Error: (err && err.message) || String(err) }, id);
            }
          };

  OnboardingPolicyLambdaLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${OnboardingPolicyLambdaFunction}'
      RetentionInDays: !Ref LambdaLogRetentionDays
      Tags:
        - Key: Purpose
          Value: iot-device-onboarding

  IoTDeviceOnboardingPolicy:
    Type: Custom::IoTDeviceOnboardingPolicy
    DependsOn: OnboardingPolicyLambdaLogGroup
    Properties:
      ServiceToken: !GetAtt OnboardingPolicyLambdaFunction.Arn
      PolicyNamePrefix: !Ref PolicyNamePrefix
      ThingName: !Ref ThingName
      TopicFilter: !Ref TopicFilter

Outputs:
  DevicePolicyName:
    Description: Name of the generated IoT device onboarding policy.
    Value: !GetAtt IoTDeviceOnboardingPolicy.PolicyName
  DevicePolicyArn:
    Description: ARN of the generated IoT device onboarding policy.
    Value: !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/${IoTDeviceOnboardingPolicy.PolicyName}'

AWSTemplateFormatVersion: "2010-09-09"

Description: >-
  Creates an hourly scheduled workflow (EventBridge rule) that invokes an AWS Step Functions
  Express state machine which paginates through AWS Organization accounts, closes accounts
  tagged with organizations:account-closure=REQUESTED that are ACTIVE using CloseAccount,
  tags them with ACKNOWLEDGED, includes throttling and eventual consistency error handling,
  and logs all execution data to a CloudWatch Logs group with 365-day retention.

Metadata:
  AWS::CloudFormation::Interface:
    ParameterGroups:
      - Label:
          default: Schedule configuration
        Parameters:
          - ScheduleExpression
      - Label:
          default: Logging configuration
        Parameters:
          - LogRetentionInDays

Parameters:
  ScheduleExpression:
    Type: String
    Default: rate(1 hour)
    Description: >-
      EventBridge schedule expression that triggers the account closure workflow.
      Defaults to running every hour.
  LogRetentionInDays:
    Type: Number
    Default: 365
    AllowedValues:
      - 1
      - 3
      - 5
      - 7
      - 14
      - 30
      - 60
      - 90
      - 120
      - 150
      - 180
      - 365
      - 400
      - 545
      - 731
      - 1827
      - 3653
    Description: >-
      Number of days that state machine execution logs are retained in CloudWatch Logs.
      Defaults to 365 days.

Resources:
  AccountClosureWorkflowLogs:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/vendedlogs/states/organizations-account-closure
      RetentionInDays: !Ref LogRetentionInDays

  StateMachineLogGroupResourcePolicy:
    Type: AWS::Logs::ResourcePolicy
    Properties:
      PolicyName: !Sub "${AWS::StackName}-stepfunctions-log-group-policy"
      PolicyDocument: !Sub |-
        {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Sid": "StepFunctionsLogGroupAccess",
              "Effect": "Allow",
              "Principal": {
                "Service": "states.amazonaws.com"
              },
              "Action": [
                "logs:CreateLogStream",
                "logs:PutLogEvents"
              ],
              "Resource": [
                "${AccountClosureWorkflowLogs.Arn}",
                "${AccountClosureWorkflowLogs.Arn}:*"
              ],
              "Condition": {
                "ArnLike": {
                  "aws:SourceArn": "arn:aws:states:${AWS::Region}:${AWS::AccountId}:stateMachine:*"
                },
                "StringEquals": {
                  "aws:SourceAccount": "${AWS::AccountId}"
                }
              }
            }
          ]
        }

  AccountClosureStateMachineRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role for the Express state machine that closes tagged Organization accounts
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
            Condition:
              StringEquals:
                aws:SourceAccount: !Ref AWS::AccountId
      Policies:
        - PolicyName: OrganizationsAccountClosureAccess
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Sid: OrganizationsAccountClosureApiActions
                Effect: Allow
                Action:
                  - organizations:ListAccounts
                  - organizations:ListTagsForResource
                  - organizations:DescribeAccount
                  - organizations:CloseAccount
                  - organizations:TagResource
                Resource: "*"
              - Sid: StepFunctionsCloudWatchLogsDeliveryManagement
                Effect: Allow
                Action:
                  - logs:CreateLogDelivery
                  - logs:GetLogDelivery
                  - logs:UpdateLogDelivery
                  - logs:DeleteLogDelivery
                  - logs:ListLogDeliveries
                  - logs:PutResourcePolicy
                  - logs:DescribeResourcePolicies
                  - logs:DescribeLogGroups
                Resource: "*"
              - Sid: StepFunctionsCloudWatchLogsWriteAccess
                Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                  - logs:DescribeLogStreams
                Resource:
                  - !GetAtt AccountClosureWorkflowLogs.Arn
                  - !Sub "${AccountClosureWorkflowLogs.Arn}:*"

  AccountClosureStateMachine:
    Type: AWS::StepFunctions::StateMachine
    DependsOn: StateMachineLogGroupResourcePolicy
    Properties:
      StateMachineName: organizations-account-closure-workflow
      StateMachineType: EXPRESS
      RoleArn: !GetAtt AccountClosureStateMachineRole.Arn
      LoggingConfiguration:
        Destinations:
          - CloudWatchLogsLogGroup:
              LogGroupArn: !GetAtt AccountClosureWorkflowLogs.Arn
        IncludeExecutionData: true
        Level: ALL
      DefinitionString: |-
        {
          "Comment": "Hourly workflow that closes AWS Organization accounts tagged with organizations:account-closure=REQUESTED, then tags them ACKNOWLEDGED.",
          "StartAt": "ListAccountsFirstPage",
          "States": {
            "ListAccountsFirstPage": {
              "Type": "Task",
              "Resource": "arn:aws:states:::aws-sdk:organizations:listAccounts",
              "Parameters": {
                "MaxResults": 20
              },
              "ResultPath": "$.page",
              "Retry": [
                {
                  "ErrorEquals": [
                    "Organizations.ThrottlingException",
                    "Organizations.TooManyRequestsException",
                    "Organizations.ConcurrentModificationException",
                    "Organizations.ServiceException",
                    "ThrottlingException",
                    "TooManyRequestsException",
                    "ConcurrentModificationException",
                    "ServiceException"
                  ],
                  "IntervalSeconds": 2,
                  "BackoffRate": 2,
                  "MaxAttempts": 6
                }
              ],
              "Next": "ProcessAccountsPage"
            },
            "ProcessAccountsPage": {
              "Type": "Map",
              "ItemsPath": "$.page.Accounts",
              "MaxConcurrency": 20,
              "ResultPath": null,
              "ItemProcessor": {
                "ProcessorConfig": {
                  "Mode": "INLINE"
                },
                "StartAt": "GetAccountTags",
                "States": {
                  "GetAccountTags": {
                    "Type": "Task",
                    "Resource": "arn:aws:states:::aws-sdk:organizations:listTagsForResource",
                    "Parameters": {
                      "ResourceId.$": "$.Id"
                    },
                    "ResultPath": "$.tagsResult",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "Organizations.ConcurrentModificationException",
                          "Organizations.ServiceException",
                          "ThrottlingException",
                          "TooManyRequestsException",
                          "ConcurrentModificationException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 2,
                        "BackoffRate": 2,
                        "MaxAttempts": 6
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": null,
                        "Next": "SkipAccount"
                      }
                    ],
                    "Next": "FindClosureRequestTag"
                  },
                  "FindClosureRequestTag": {
                    "Type": "Map",
                    "ItemsPath": "$.tagsResult.Tags",
                    "ResultPath": "$.closureTagValues",
                    "ItemProcessor": {
                      "ProcessorConfig": {
                        "Mode": "INLINE"
                      },
                      "StartAt": "IsClosureRequestTag",
                      "States": {
                        "IsClosureRequestTag": {
                          "Type": "Choice",
                          "Choices": [
                            {
                              "And": [
                                {
                                  "Variable": "$.Key",
                                  "StringEquals": "organizations:account-closure"
                                },
                                {
                                  "Variable": "$.Value",
                                  "StringEquals": "REQUESTED"
                                }
                              ],
                              "Next": "ReturnTagValue"
                            }
                          ],
                          "Default": "ReturnEmptyValue"
                        },
                        "ReturnTagValue": {
                          "Type": "Pass",
                          "InputPath": "$.Value",
                          "End": true
                        },
                        "ReturnEmptyValue": {
                          "Type": "Pass",
                          "Parameters": {
                            "value": ""
                          },
                          "OutputPath": "$.value",
                          "End": true
                        }
                      }
                    },
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": null,
                        "Next": "SkipAccount"
                      }
                    ],
                    "Next": "EvaluateClosureRequest"
                  },
                  "EvaluateClosureRequest": {
                    "Type": "Pass",
                    "Parameters": {
                      "requested.$": "States.ArrayContains($.closureTagValues, 'REQUESTED')"
                    },
                    "ResultPath": "$.closureRequest",
                    "Next": "IsRequestedForClosure"
                  },
                  "IsRequestedForClosure": {
                    "Type": "Choice",
                    "Choices": [
                      {
                        "Variable": "$.closureRequest.requested",
                        "BooleanEquals": true,
                        "Next": "DescribeAccount"
                      }
                    ],
                    "Default": "SkipAccount"
                  },
                  "DescribeAccount": {
                    "Type": "Task",
                    "Resource": "arn:aws:states:::aws-sdk:organizations:describeAccount",
                    "Parameters": {
                      "AccountId.$": "$.Id"
                    },
                    "ResultPath": "$.describeResult",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "Organizations.ConcurrentModificationException",
                          "Organizations.ServiceException",
                          "ThrottlingException",
                          "TooManyRequestsException",
                          "ConcurrentModificationException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 2,
                        "BackoffRate": 2,
                        "MaxAttempts": 6
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": null,
                        "Next": "SkipAccount"
                      }
                    ],
                    "Next": "IsAccountActive"
                  },
                  "IsAccountActive": {
                    "Type": "Choice",
                    "Choices": [
                      {
                        "Variable": "$.describeResult.Account.Status",
                        "StringEquals": "ACTIVE",
                        "Next": "CloseAccount"
                      }
                    ],
                    "Default": "SkipAccount"
                  },
                  "CloseAccount": {
                    "Type": "Task",
                    "Resource": "arn:aws:states:::aws-sdk:organizations:closeAccount",
                    "Parameters": {
                      "AccountId.$": "$.Id"
                    },
                    "ResultPath": "$.closeResult",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ConcurrentModificationException",
                          "ConcurrentModificationException",
                          "Organizations.AccountNotFoundException",
                          "AccountNotFoundException"
                        ],
                        "IntervalSeconds": 5,
                        "BackoffRate": 2,
                        "MaxAttempts": 3
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "Organizations.ServiceException",
                          "ThrottlingException",
                          "TooManyRequestsException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 2,
                        "BackoffRate": 2,
                        "MaxAttempts": 6
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": null,
                        "Next": "SkipAccount"
                      }
                    ],
                    "Next": "MarkAccountAcknowledged"
                  },
                  "MarkAccountAcknowledged": {
                    "Type": "Task",
                    "Resource": "arn:aws:states:::aws-sdk:organizations:tagResource",
                    "Parameters": {
                      "ResourceId.$": "$.Id",
                      "Tags": [
                        {
                          "Key": "organizations:account-closure",
                          "Value": "ACKNOWLEDGED"
                        }
                      ]
                    },
                    "ResultPath": "$.acknowledgeResult",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ConcurrentModificationException",
                          "ConcurrentModificationException",
                          "Organizations.AccountNotFoundException",
                          "AccountNotFoundException"
                        ],
                        "IntervalSeconds": 5,
                        "BackoffRate": 2,
                        "MaxAttempts": 3
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "Organizations.ServiceException",
                          "ThrottlingException",
                          "TooManyRequestsException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 2,
                        "BackoffRate": 2,
                        "MaxAttempts": 6
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": null,
                        "Next": "SkipAccount"
                      }
                    ],
                    "Next": "AccountClosureComplete"
                  },
                  "AccountClosureComplete": {
                    "Type": "Pass",
                    "Parameters": {
                      "accountId.$": "$.Id",
                      "accountName.$": "$.Name",
                      "result": "closed-and-acknowledged"
                    },
                    "End": true
                  },
                  "SkipAccount": {
                    "Type": "Pass",
                    "Parameters": {
                      "accountId.$": "$.Id",
                      "result": "skipped"
                    },
                    "End": true
                  }
                }
              },
              "Catch": [
                {
                  "ErrorEquals": [
                    "States.ALL"
                  ],
                  "ResultPath": null,
                  "Next": "MorePagesAvailable"
                }
              ],
              "Next": "MorePagesAvailable"
            },
            "MorePagesAvailable": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.page.NextToken",
                  "IsPresent": true,
                  "Next": "ListAccountsNextPage"
                }
              ],
              "Default": "WorkflowComplete"
            },
            "ListAccountsNextPage": {
              "Type": "Task",
              "Resource": "arn:aws:states:::aws-sdk:organizations:listAccounts",
              "Parameters": {
                "MaxResults": 20,
                "NextToken.$": "$.page.NextToken"
              },
              "ResultPath": "$.page",
              "Retry": [
                {
                  "ErrorEquals": [
                    "Organizations.ThrottlingException",
                    "Organizations.TooManyRequestsException",
                    "Organizations.ConcurrentModificationException",
                    "Organizations.ServiceException",
                    "ThrottlingException",
                    "TooManyRequestsException",
                    "ConcurrentModificationException",
                    "ServiceException"
                  ],
                  "IntervalSeconds": 2,
                  "BackoffRate": 2,
                  "MaxAttempts": 6
                }
              ],
              "Next": "ProcessAccountsPage"
            },
            "WorkflowComplete": {
              "Type": "Succeed"
            }
          }
        }

  AccountClosureScheduleRuleRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows EventBridge to start the account closure state machine on a schedule
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: events.amazonaws.com
            Action: sts:AssumeRole
            Condition:
              StringEquals:
                aws:SourceAccount: !Ref AWS::AccountId
      Policies:
        - PolicyName: StartAccountClosureStateMachine
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Sid: AllowStartAccountClosureExecution
                Effect: Allow
                Action: states:StartExecution
                Resource: !GetAtt AccountClosureStateMachine.Arn

  AccountClosureScheduleRule:
    Type: AWS::Events::Rule
    Properties:
      Name: organizations-account-closure-schedule
      Description: Hourly trigger for the Organizations account closure workflow
      ScheduleExpression: !Ref ScheduleExpression
      State: ENABLED
      Targets:
        - Id: AccountClosureStateMachine
          Arn: !GetAtt AccountClosureStateMachine.Arn
          RoleArn: !GetAtt AccountClosureScheduleRuleRole.Arn
          Input: '{"trigger":"hourly-schedule","workflow":"organizations-account-closure"}'

Outputs:
  StateMachineArn:
    Description: ARN of the account closure Express state machine
    Value: !GetAtt AccountClosureStateMachine.Arn
    Export:
      Name: !Sub "${AWS::StackName}-StateMachineArn"
  StateMachineName:
    Description: Name of the account closure Express state machine
    Value: !GetAtt AccountClosureStateMachine.Name
    Export:
      Name: !Sub "${AWS::StackName}-StateMachineName"
  StateMachineRoleArn:
    Description: IAM role used by the account closure state machine
    Value: !GetAtt AccountClosureStateMachineRole.Arn
    Export:
      Name: !Sub "${AWS::StackName}-StateMachineRoleArn"
  CloudWatchLogGroupArn:
    Description: CloudWatch Logs group storing all state machine execution data
    Value: !GetAtt AccountClosureWorkflowLogs.Arn
    Export:
      Name: !Sub "${AWS::StackName}-LogGroupArn"
  ScheduleRuleArn:
    Description: ARN of the hourly EventBridge schedule rule
    Value: !GetAtt AccountClosureScheduleRule.Arn
    Export:
      Name: !Sub "${AWS::StackName}-ScheduleRuleArn"

AWSTemplateFormatVersion: "2010-09-09"
Description: >-
  Step Functions calculator demo. Provisions the Calculator-StateMachine state
  machine, which routes on the requested operator (add, subtract, multiply,
  divide) and invokes the Calculator Lambda function (Node.js 24.x, inline
  code) to perform the calculation. Unknown operators fail the execution. The
  template also provisions the required IAM roles and a 3-day-retention
  CloudWatch log group for the Lambda.

Resources:
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  CalculatorLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Description: Execution role for the Calculator Lambda function to write logs to CloudWatch
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole

  CalculatorLambda:
    Type: AWS::Lambda::Function
    DependsOn: CalculatorLogGroup
    Properties:
      FunctionName: Calculator
      Description: Performs add, subtract, multiply, and divide operations for the Step Functions calculator demo
      Runtime: nodejs24.x
      Architectures:
        - x86_64
      Handler: index.handler
      MemorySize: 128
      Timeout: 10
      Role: !GetAtt CalculatorLambdaRole.Arn
      Code:
        ZipFile: |
          'use strict';

          exports.handler = async (event) => {
            const operator = event && event.operator;
            const operands = event && event.operands;

            if (!operator || !Array.isArray(operands) || operands.length === 0) {
              throw new Error('Invalid input: expected {"operator": "add|subtract|multiply|divide", "operands": [<number>, ...]}');
            }

            if (operands.some((current) => typeof current !== 'number' || !Number.isFinite(current))) {
              throw new Error('All operands must be finite numbers.');
            }

            let result;
            switch (operator) {
              case 'add':
                result = operands.reduce((accumulator, current) => accumulator + current, 0);
                break;
              case 'subtract':
                result = operands.reduce((accumulator, current) => accumulator - current);
                break;
              case 'multiply':
                result = operands.reduce((accumulator, current) => accumulator * current, 1);
                break;
              case 'divide':
                if (operands.some((current) => current === 0)) {
                  throw new Error('Division by zero is not allowed.');
                }
                result = operands.reduce((accumulator, current) => accumulator / current);
                break;
              default:
                throw new Error('Unsupported operator: ' + operator);
            }

            return {
              operator: operator,
              operands: operands,
              result: result
            };
          };

  CalculatorStateMachineRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: !Sub states.${AWS::Region}.amazonaws.com
            Action: sts:AssumeRole
      Description: Role assumed by the Calculator state machine to invoke the Calculator Lambda
      Policies:
        - PolicyName: CalculatorStateMachineInvokeLambda
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - lambda:InvokeFunction
                Resource: !GetAtt CalculatorLambda.Arn

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      StateMachineType: STANDARD
      RoleArn: !GetAtt CalculatorStateMachineRole.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Calculator demo: routes the requested operator to the Calculator Lambda",
          "StartAt": "RouteOperation",
          "States": {
            "RouteOperation": {
              "Type": "Choice",
              "Comment": "Routes to the matching operation; unknown operators fail the execution",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "AddOperation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "SubtractOperation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "MultiplyOperation"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "DivideOperation"
                }
              ],
              "Default": "UnsupportedOperator"
            },
            "AddOperation": {
              "Type": "Task",
              "Comment": "Invokes the Calculator Lambda to perform addition",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${CalculatorLambda.Arn}",
                "Payload.$": "$"
              },
              "ResultSelector": {
                "result.$": "$.Payload.result"
              },
              "ResultPath": "$.calculation",
              "End": true
            },
            "SubtractOperation": {
              "Type": "Task",
              "Comment": "Invokes the Calculator Lambda to perform subtraction",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${CalculatorLambda.Arn}",
                "Payload.$": "$"
              },
              "ResultSelector": {
                "result.$": "$.Payload.result"
              },
              "ResultPath": "$.calculation",
              "End": true
            },
            "MultiplyOperation": {
              "Type": "Task",
              "Comment": "Invokes the Calculator Lambda to perform multiplication",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${CalculatorLambda.Arn}",
                "Payload.$": "$"
              },
              "ResultSelector": {
                "result.$": "$.Payload.result"
              },
              "ResultPath": "$.calculation",
              "End": true
            },
            "DivideOperation": {
              "Type": "Task",
              "Comment": "Invokes the Calculator Lambda to perform division",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${CalculatorLambda.Arn}",
                "Payload.$": "$"
              },
              "ResultSelector": {
                "result.$": "$.Payload.result"
              },
              "ResultPath": "$.calculation",
              "End": true
            },
            "UnsupportedOperator": {
              "Type": "Fail",
              "Comment": "Terminal failure for unknown operators",
              "Error": "CalculatorUnsupportedOperator",
              "Cause": "The supplied operator is not supported. Supported operators are: add, subtract, multiply, divide."
            }
          }
        }

Outputs:
  SampleInput:
    Description: Sample input format accepted by the Calculator state machine
    Value: '{"operator": "add", "operands": [1, 2]}'
  CalculatorStateMachineArn:
    Description: ARN of the Calculator state machine
    Value: !Ref CalculatorStateMachine
  CalculatorStateMachineName:
    Description: Name of the Calculator state machine
    Value: !GetAtt CalculatorStateMachine.Name
  CalculatorLambdaArn:
    Description: ARN of the Calculator Lambda function
    Value: !GetAtt CalculatorLambda.Arn
  CalculatorLogGroupName:
    Description: CloudWatch log group for the Calculator Lambda function
    Value: !Ref CalculatorLogGroup

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Self-contained AWS AppSync GraphQL API named TodoAPIwithJs with API key authentication,
  backed by a DynamoDB table with a global secondary index on the owner attribute and
  JavaScript pipeline resolvers providing full CRUD (create, update, delete, get, list),
  a query by owner against the index, and real-time subscriptions for create, update,
  and delete events.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      TableName: !Sub '${AWS::StackName}-TodoTable'
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: todos-by-owner
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:DeleteItem
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:Query
                  - dynamodb:Scan
                  - dynamodb:UpdateItem
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY

  GraphQLApiApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          content: String
          owner: String
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        enum ModelSortDirection {
          ASC
          DESC
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          title: String!
          content: String
          owner: String
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          content: String
          owner: String
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, sortDirection: ModelSortDirection, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo: Todo @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: create_todo_function
      Description: JavaScript function that creates a new Todo item in the DynamoDB table
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            id: id,
            title: input.title,
            createdAt: now,
            updatedAt: now,
          };
          if (input.content !== undefined) {
            item.content = input.content;
          }
          if (input.owner !== undefined) {
            item.owner = input.owner;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: update_todo_function
      Description: JavaScript function that updates an existing Todo item in the DynamoDB table
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const names = {};
          const vals = {};
          const sets = [];
          if (input.title !== undefined) {
            names['#title'] = 'title';
            vals[':title'] = input.title;
            sets.push('#title = :title');
          }
          if (input.content !== undefined) {
            names['#content'] = 'content';
            vals[':content'] = input.content;
            sets.push('#content = :content');
          }
          if (input.owner !== undefined) {
            names['#owner'] = 'owner';
            vals[':owner'] = input.owner;
            sets.push('#owner = :owner');
          }
          names['#updatedAt'] = 'updatedAt';
          vals[':updatedAt'] = util.time.nowISO8601();
          sets.push('#updatedAt = :updatedAt');
          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: names,
              expressionValues: util.dynamodb.toMapValues(vals),
            },
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: delete_todo_function
      Description: JavaScript function that deletes a Todo item from the DynamoDB table
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: get_todo_function
      Description: JavaScript function that gets a single Todo item by id from the DynamoDB table
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = ctx.args.id;
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: list_todos_function
      Description: JavaScript function that lists Todo items with limit and pagination
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const scanRequest = {
            operation: 'Scan',
            select: 'ALL_ATTRIBUTES',
          };
          if (ctx.args.limit !== undefined) {
            scanRequest.limit = ctx.args.limit;
          }
          if (ctx.args.nextToken !== undefined) {
            scanRequest.nextToken = ctx.args.nextToken;
          }
          return scanRequest;
        }

        export function response(ctx) {
          const result = {
            items: ctx.result.items,
          };
          if (ctx.result.nextToken !== undefined) {
            result.nextToken = ctx.result.nextToken;
          }
          return result;
        }

  TodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: todos_by_owner_function
      Description: JavaScript function that queries the todos-by-owner global secondary index by owner
      DataSourceName: !GetAtt TodoDataSource.Name
      FunctionVersion: '2018-05-29'
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const forward = ctx.args.sortDirection !== 'DESC';
          const queryRequest = {
            operation: 'Query',
            index: 'todos-by-owner',
            select: 'ALL_ATTRIBUTES',
            scanIndexForward: forward,
            query: {
              expression: '#owner = :owner',
              expressionNames: {
                '#owner': 'owner',
              },
              expressionValues: util.dynamodb.toMapValues({
                ':owner': ctx.args.owner,
              }),
            },
          };
          if (ctx.args.limit !== undefined) {
            queryRequest.limit = ctx.args.limit;
          }
          if (ctx.args.nextToken !== undefined) {
            queryRequest.nextToken = ctx.args.nextToken;
          }
          return queryRequest;
        }

        export function response(ctx) {
          const result = {
            items: ctx.result.items,
          };
          if (ctx.result.nextToken !== undefined) {
            result.nextToken = ctx.result.nextToken;
          }
          return result;
        }

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt TodosByOwnerFunction.FunctionId

Outputs:
  GraphQLApiURL:
    Description: Endpoint URL of the TodoAPIwithJs GraphQL API
    Value: !GetAtt GraphQLApi.GraphQLUrl
  GraphQLApiId:
    Description: Unique AppSync API identifier
    Value: !GetAtt GraphQLApi.ApiId
  GraphQLApiKey:
    Description: API key for authenticating requests to the GraphQL API
    Value: !GetAtt GraphQLApiApiKey.ApiKey
  TodoTableName:
    Description: Name of the DynamoDB table backing the GraphQL API
    Value: !Ref TodoTable
  TodoTableArn:
    Description: ARN of the DynamoDB table backing the GraphQL API
    Value: !GetAtt TodoTable.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Creates the SimpleTodoAPI AWS AppSync GraphQL API backed by a single DynamoDB
  table. All resolvers use JavaScript (APPSYNC_JS runtime) instead of VTL
  mapping templates, and the API uses API key authentication with a key created
  by this template for straightforward testing.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: !Sub '${AWS::StackName}-todos'
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      BillingMode: PAY_PER_REQUEST
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Service role assumed by AppSync to read and write the Todo DynamoDB table
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: 'sts:AssumeRole'
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/owner-index'

  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          name: String!
          description: String
          priority: Int
          owner: String!
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }

        input CreateTodoInput {
          name: String!
          description: String
          priority: Int
          owner: String!
        }

        input UpdateTodoInput {
          id: ID!
          name: String
          description: String
          priority: Int
          owner: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo!
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        schema {
          query: Query
          mutation: Mutation
        }

  GraphQLApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: Default API key for SimpleTodoAPI testing (defaults to 7 day validity)

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoTableDataSource
      Description: Single DynamoDB data source backed by the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        AwsRegion: !Ref AWS::Region
        TableName: !Ref TodoTable

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: UNIT
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { input } = ctx.args;
          const now = util.time.nowISO8601();
          const attributeValues = {
            name: input.name,
            owner: input.owner,
            createdAt: now,
            updatedAt: now
          };
          if (input.description !== undefined && input.description !== null) {
            attributeValues.description = input.description;
          }
          if (input.priority !== undefined && input.priority !== null) {
            attributeValues.priority = input.priority;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: util.autoId() }),
            attributeValues: util.dynamodb.toMapValues(attributeValues)
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type, result);
          }
          return result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: UNIT
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { input } = ctx.args;
          const setActions = ['SET #updatedAt = :updatedAt'];
          const expressionNames = { '#updatedAt': 'updatedAt' };
          const expressionValues = {
            ':updatedAt': util.dynamodb.toDynamoDB(util.time.nowISO8601())
          };

          if (input.name !== undefined && input.name !== null) {
            setActions.push('#name = :name');
            expressionNames['#name'] = 'name';
            expressionValues[':name'] = util.dynamodb.toDynamoDB(input.name);
          }

          if (input.description !== undefined && input.description !== null) {
            setActions.push('#description = :description');
            expressionNames['#description'] = 'description';
            expressionValues[':description'] = util.dynamodb.toDynamoDB(input.description);
          }

          if (input.priority !== undefined && input.priority !== null) {
            setActions.push('#priority = :priority');
            expressionNames['#priority'] = 'priority';
            expressionValues[':priority'] = util.dynamodb.toDynamoDB(input.priority);
          }

          if (input.owner !== undefined && input.owner !== null) {
            setActions.push('#owner = :owner');
            expressionNames['#owner'] = 'owner';
            expressionValues[':owner'] = util.dynamodb.toDynamoDB(input.owner);
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: setActions.join(', '),
              expressionNames: expressionNames,
              expressionValues: expressionValues
            }
          };
        }

        export function response(ctx) {
          const { error, result } = ctx;
          if (error) {
            util.error(error.message, error.type, result);
          }
          return result;
        }

